---
// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
// Agent lanes: Several agents working in parallel, each with its own lane and hand-offs.
// The markup, CSS and script are designme.dev's own, run by the shared core in ../core, which mounts the component when it scrolls
// into view and plays its demo. To show your own data, change agent-lanes.js. The markup is kept exactly as it is (is:raw).
import type { HTMLAttributes } from 'astro/types';
import '../core/designme.css';
import './agent-lanes.css';

export interface Props extends HTMLAttributes<'div'> {
  /** "soft" draws it in the Soft style. Leave it out for Blueprint, or for the style set on <html> (data-style="soft") */
  'data-style'?: 'soft';
}
const { class: className, ...rest } = Astro.props;
---
<div class:list={['card', 'wide', 'bare', className]} data-c="agent-lanes" {...rest}>
  <div class="stage-in"><Fragment is:raw>
<div class="aln panel">
  <div class="aln-h"><span class="aln-ic"><svg class="i s"><use href="#i-users"/></svg></span><span class="aln-t">3 agents working</span><span class="aln-m muted num">0:00</span><span class="aln-ct num">0 of 9 steps</span><button class="pill soft sm aln-pause"><svg class="i xs"><use href="#i-pause"/></svg>Pause all</button></div>
  <div class="aln-rows"></div>
</div>
  </Fragment></div>
</div>
<script>
  import './agent-lanes.js';
</script>

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Agent lanes ---------- */
/* each agent has its own hue (--dm-c, with its tint --dm-cb): its badge, its track, its tag and its stretch of the relay line that
   joins the badges. A hand-off sends a light down that line from one agent to the next, and the stretch it crossed stays lit */
.aln{padding:var(--dm-s-2)}
/* the lanes' marks (tracks, lines, a finished badge) in livelier versions of the agents' hues, each 3:1 on the surface; their
   text keeps the agent's text colour. Dark mode's agent colours are light already, so they are used as they are */
.aln{--dm-aln-pb:#2a7bff;--dm-aln-pm:#1fa66a;--dm-aln-pl:#7a5af5}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]) .aln{--dm-aln-pb:var(--dm-pb);--dm-aln-pm:var(--dm-pm);--dm-aln-pl:var(--dm-pl)}}
:root[data-theme="dark"] .aln{--dm-aln-pb:var(--dm-pb);--dm-aln-pm:var(--dm-pm);--dm-aln-pl:var(--dm-pl)}
/* on a card the lanes sit centred in the room kept for their tallest moment, and glide as a hand-off line opens and shuts */
.stage-in:has(>.aln){display:flex;flex-direction:column;justify-content:center}
.aln-h{display:flex;align-items:center;gap:10px;padding:var(--dm-s-2) 10px 10px}
.aln-ic{color:var(--dm-fg2);display:grid;transition:color .3s}
.aln.fin .aln-ic{color:var(--dm-ok)}
.aln-t{font-weight:500}
.aln-m{font-size:12.5px}
.aln-ct{font-size:12.5px;color:var(--dm-muted);margin-right:auto;white-space:nowrap}
.aln-ct::before{content:"·";margin-right:6px}
.aln-rows{position:relative}
.aln-rows>*{position:relative}
.aln-lane{border-radius:calc(14px * var(--dm-rk));transition:background .3s}
@media (hover:hover) and (pointer:fine){.aln-lane:hover{background:var(--dm-row)}}
/* the lane at work carries a wash of its hue from the left */
.aln-lane[data-s="working"]{background:linear-gradient(90deg,color-mix(in srgb,var(--dm-c) 8%,transparent),transparent 72%)}
@media (hover:hover) and (pointer:fine){.aln-lane[data-s="working"]:hover{background:linear-gradient(90deg,color-mix(in srgb,var(--dm-c) 8%,transparent),transparent 72%),var(--dm-row)}}
/* the relay line runs from badge to badge, through the lanes and the hand-offs between them, and stops short of each badge */
.aln-rows>*::before{content:"";position:absolute;left:26px;width:2px;top:0;bottom:0;background:var(--dm-line);pointer-events:none}
.aln-lane::before{top:48px}
.aln-lane:last-child::before{display:none}
.aln-lane::after{content:"";position:absolute;left:26px;width:2px;top:0;height:6px;background:var(--dm-line);pointer-events:none}
.aln-lane:first-child::after{display:none}
/* a stretch that has carried a hand-off is drawn by its one lit stroke (.aln-pk, below), so the grey under it steps aside
   and the line from badge to badge stays a single clean line */
.aln-rows>.aln-lane.sent::before,.aln-rows>.aln-lane.got::after,.aln-rows>.aln-hf.lit::before{background:transparent}
.aln-row{display:grid;grid-template-columns:34px minmax(0,1.2fr) minmax(0,1fr) auto;align-items:center;gap:var(--dm-s-3);width:100%;padding:10px;text-align:left}
.aln-av{position:relative;width:34px;height:34px;border-radius:calc(11px * var(--dm-rk));display:grid;place-items:center;color:var(--dm-c);background:var(--dm-cb);transition:color .4s,background .4s}
.aln-av::before{content:"";position:absolute;inset:0;border-radius:inherit;pointer-events:none}
.aln-lane[data-s="working"] .aln-av{animation:alnbreathe 2.4s var(--dm-ease-io) infinite}
@keyframes alnbreathe{0%,100%{box-shadow:0 0 0 1px color-mix(in srgb,var(--dm-c) 22%,transparent),0 0 0 1px color-mix(in srgb,var(--dm-fg) 0%,transparent)}50%{box-shadow:0 0 0 1px color-mix(in srgb,var(--dm-c) 22%,transparent),0 0 0 5px color-mix(in srgb,var(--dm-fg) 6%,transparent)}}
/* the badge that takes a hand-off rings once as the light reaches it */
.aln-av.ping::before{animation:alnping .9s var(--dm-ease)}
@keyframes alnping{from{box-shadow:0 0 0 0 color-mix(in srgb,var(--dm-fg) 20%,transparent)}to{box-shadow:0 0 0 12px color-mix(in srgb,var(--dm-fg) 0%,transparent)}}
/* the lane at work is tinted, so what sits on the tint (its badge, its tag) is lifted onto the surface to stand clear of it */
.aln-lane[data-s="working"] .aln-av,.aln-lane[data-s="working"] .aln-tg{background:var(--dm-surface);box-shadow:0 0 0 1px color-mix(in srgb,var(--dm-c) 22%,transparent)}
/* a finished agent's badge fills with its hue */
.aln-lane[data-s="done"] .aln-av{background:var(--dm-cm);color:var(--dm-surface)}
.aln-who{min-width:0}
.aln-n{display:block;font-weight:500;font-size:13.5px}
.aln-a{display:block;font-size:12.5px;color:var(--dm-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.aln-a.live{color:var(--dm-fg2)}
/* the track: one part a step. Finished parts are solid, the one in hand fills as the agent works, with a light running along it */
.aln-tr{display:flex;gap:3px}
.aln-tr i{flex:1;height:10px;border-radius:5px;background:color-mix(in srgb,var(--dm-cm) 13%,var(--dm-line));position:relative;overflow:hidden}
.aln-tr i::after{content:"";position:absolute;inset:0;border-radius:inherit;background:var(--dm-cm);transform:scaleX(var(--dm-p,0));transform-origin:left;transition:transform .25s linear}
.aln-tr i.on::after{transform:scaleX(1);transition:transform .5s var(--dm-ease)}
.aln-tr i.run::after{background:linear-gradient(90deg,var(--dm-cm) 0 30%,color-mix(in srgb,var(--dm-cm) 30%,var(--dm-surface)) 50%,var(--dm-cm) 70% 100%) 0 0/250% 100%;animation:alnsheen 1.6s linear infinite}
/* given no step progress, the part in hand fills part way and keeps its light */
.aln-tr i.run.ind::after{transform:scaleX(.6);transition:transform 2.4s var(--dm-ease)}
@keyframes alnsheen{from{background-position:100% 0}to{background-position:-150% 0}}
.aln-st{min-width:92px;display:flex;justify-content:flex-end}
.aln-tg{background:var(--dm-cb);color:var(--dm-c)}
.aln-tg .spin{width:9px;height:9px}
.aln-det{padding:0 10px 10px 56px;font-size:12.5px;color:var(--dm-fg2)}
.aln-det div{display:flex;align-items:center;gap:var(--dm-s-2);padding:3px 0}
.aln-det div::before{content:"";width:5px;height:5px;border-radius:50%;background:var(--dm-c);flex:none}
.aln-det .muted{margin-left:auto}
/* a hand-off opens a line between the lanes, glides the lanes below down and closes again */
.aln-hf{transition-duration:var(--dm-t-slow)}
.aln-hand{padding:6px 10px 6px 56px;font-size:12.5px;line-height:18px;color:var(--dm-fg2)}
.aln-hand b{font-weight:500}
.aln-hand .f{color:var(--dm-from)}.aln-hand .t{color:var(--dm-to)}
/* the hand-off draws the relay line from the sender's badge down to the taker's, in the gap between them (it never passes
   over a badge): a stroke that fills from the sender's hue into the taker's, then stays as the lit stretch (owner, 4 Nov).
   It is one element from badge to badge that follows them as the lanes move, so there is never a second line under it */
.aln-rows>.aln-pk::before{display:none}
.aln-pk{position:absolute;left:26px;top:0;width:2px;background:linear-gradient(var(--dm-from),var(--dm-to));transform-origin:50% 0;pointer-events:none;z-index:2}
@media (max-width:600px){
  .aln-row{grid-template-columns:34px minmax(0,1fr) auto;row-gap:var(--dm-s-2)}
  .aln-tr{grid-column:2 / -1;grid-row:2}
  .aln-lane::before{top:48px}
  .aln-ct{display:none}
  .aln-m{margin-right:auto}
}
@media (max-width:400px){.aln-ic{display:none}}
:root:not([data-style="soft"]) .aln-rows>*:not(:where([data-style="soft"],[data-style="soft"] *))::before,:root:not([data-style="soft"]) .aln-lane:not(:where([data-style="soft"],[data-style="soft"] *))::after{width:1px;left:26.5px;background:repeating-linear-gradient(var(--dm-rail) 0 3px,transparent 3px 6px)}
:root:not([data-style="soft"]) .aln-rows>.aln-lane.sent:not(:where([data-style="soft"],[data-style="soft"] *))::before,:root:not([data-style="soft"]) .aln-rows>.aln-lane.got:not(:where([data-style="soft"],[data-style="soft"] *))::after,:root:not([data-style="soft"]) .aln-rows>.aln-hf.lit:not(:where([data-style="soft"],[data-style="soft"] *))::before{background:transparent}
:root:not([data-style="soft"]) .aln-lane[data-s="working"] :is(.aln-av,.aln-tg):not(:where([data-style="soft"],[data-style="soft"] *)){box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-c) 45%,transparent)}
:root:not([data-style="soft"]) .aln-av:not(:where([data-style="soft"],[data-style="soft"] *)){box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-c) 35%,transparent)}
:root:not([data-style="soft"]) .aln-lane[data-s="working"] .aln-av:not(:where([data-style="soft"],[data-style="soft"] *)){animation:alnbp 1.1s steps(1,end) infinite}
@keyframes alnbp{0%,55%{box-shadow:inset 0 0 0 1px var(--dm-c)}56%,100%{box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-c) 35%,transparent)}}
:root:not([data-style="soft"]) .aln-lane[data-s="working"]:not(:where([data-style="soft"],[data-style="soft"] *)){background:color-mix(in srgb,var(--dm-c) 5%,transparent)}
:root:not([data-style="soft"]) .aln-tr i:not(:where([data-style="soft"],[data-style="soft"] *)){height:8px}
:root:not([data-style="soft"]) .aln-tr i.run:not(:where([data-style="soft"],[data-style="soft"] *))::after{background:repeating-linear-gradient(135deg,var(--dm-cm) 0 4px,color-mix(in srgb,var(--dm-cm) 55%,var(--dm-surface)) 4px 7px);animation:none}
:root:not([data-style="soft"]) .aln-pk:not(:where([data-style="soft"],[data-style="soft"] *)){width:1px;left:26.5px;border-radius:0;background:var(--dm-to)}
:root:not([data-style="soft"]) .aln-av.ping:not(:where([data-style="soft"],[data-style="soft"] *))::before{animation:alnpingbp .6s steps(3,end)}
@keyframes alnpingbp{from{box-shadow:0 0 0 1px var(--dm-c)}to{box-shadow:0 0 0 7px transparent}}

// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
import { $, $$, DM, I, REDUCE, enter, hold, html, swap } from '../core/core.js';
DM.def('agent-lanes', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{users}', I('users')).replace('{pause}', I('pause','xs'));
  // each agent has a hue of its own (t names the palette slot): its badge, its track, its tag and its stretch of the relay line
  const L = [
    { n:'Researcher', ic:'search', t:'pb', acts:['Reading competitor sites','Comparing 5 pricing pages','Writing the brief'], log:['Read stripe.com/pricing','Read linear.app/pricing','Noted 3 patterns'] },
    { n:'Designer', ic:'palette', t:'pl', wait:'Waiting for the brief', acts:['Laying out pricing cards','Setting type and spacing','Exporting frames'], log:['Made 3 card variants','Applied spacing tokens','Exported 4 frames'] },
    { n:'Reviewer', ic:'eye', t:'pm', wait:'Waiting for the designer', acts:['Checking contrast','Checking copy','Signing off'], log:['Contrast passes AA','Fixed 2 lines of copy','Approved'] }
  ];
  const root = $('.aln', r), rows = $('.aln-rows', r), ct = $('.aln-ct', r), STEPS = L.length * 3;
  L.forEach(l => {
    l.el = html(`<div class="aln-lane" data-s="queued" style="--dm-c:var(--dm-${l.t});--dm-cb:var(--dm-${l.t}-bg);--dm-cm:var(--dm-aln-${l.t},var(--dm-${l.t}))"><button class="aln-row" aria-expanded="false"><span class="aln-av">${I(l.ic)}</span><span class="aln-who"><span class="aln-n">${l.n}</span><span class="aln-a">${l.wait || 'Queued'}</span></span><span class="aln-tr" aria-hidden="true"><i></i><i></i><i></i></span><span class="aln-st"><span class="tag">Queued</span></span></button><div class="fold shut"><div><div class="aln-det"></div></div></div></div>`);
    rows.appendChild(l.el); const b = $('.aln-row', l.el), f = $('.fold', l.el);
    b.onclick = () => { const s = f.classList.toggle('shut'); b.setAttribute('aria-expanded', !s); };
  });
  const TAG = { queued:'<span class="tag">Queued</span>', waiting:`<span class="tag">${I('clock','xs')}Waiting</span>`, working:'<span class="tag aln-tg"><span class="spin"></span>Working</span>', paused:'<span class="tag warn">Paused</span>', done:`<span class="tag ok">${I('check','xs')}Done</span>` };
  const state = (l, s) => { l.el.dataset.s = s; const t = $('.aln-st', l.el); t.innerHTML = TAG[s]; enter(t.firstElementChild); };
  const act = (l, t, live) => { const a = $('.aln-a', l.el); a.classList.toggle('live', !!live); a.classList.toggle('shim', !!live); swap(a, t); };
  let paused = false, secs = 0, finished = false, steps = 0;
  const count = () => swap(ct, `${steps} of ${STEPS} steps`);
  const pb = $('.aln-pause', r);
  pb.onclick = () => { paused = !paused; pb.innerHTML = I(paused ? 'play' : 'pause','xs') + (paused ? 'Resume' : 'Pause all'); swap($('.aln-t', r), paused ? 'All agents paused' : '3 agents working');
    L.forEach(l => { if (l.running){ state(l, paused ? 'paused' : 'working'); $('.aln-a', l.el).classList.toggle('shim', !paused); } }); };
  c.every(1000, () => { if (!paused && !finished){ secs++; $('.aln-m', r).textContent = Math.floor(secs / 60) + ':' + String(secs % 60).padStart(2, '0'); } });
  // time only passes for the agents while they aren't paused; each() hears how far through the wait they are
  const hold = async (ms, each) => { let t = 0; while (t < ms){ await c.wait(100); if (!paused){ t += 100; each && each(t / ms); } } };
  async function work(l){
    l.running = true; state(l, 'working');
    const bars = $$('.aln-tr i', l.el), det = $('.aln-det', l.el);
    for (let i = 0; i < 3; i++){
      bars[i].classList.add('run'); act(l, l.acts[i], true);
      await hold(1500, p => bars[i].style.setProperty('--dm-p', p.toFixed(3)));
      bars[i].classList.replace('run', 'on'); steps++; count();
      const d = html(`<div><span>${l.log[i]}</span><span class="muted">${secs}s</span></div>`); det.appendChild(d); enter(d);
    }
    l.running = false; act(l, l.log[2]); state(l, 'done');
  }
  // the relay line draws itself from one badge down to the next, the badge it reaches rings, and the stroke stays as the lit
  // stretch: one line from badge to badge that follows them as the hand-off line opens and shuts (the grey under it steps aside)
  const links = [];
  const place = k => { const rr = rows.getBoundingClientRect(), a = $('.aln-av', k.from.el).getBoundingClientRect(), b = $('.aln-av', k.to.el).getBoundingClientRect();
    const y0 = a.bottom - rr.top + 4, y1 = b.top - rr.top - 4; k.pk.style.top = y0 + 'px'; k.pk.style.height = Math.max(0, y1 - y0) + 'px'; };
  const ro = new ResizeObserver(() => links.forEach(place)); ro.observe(rows); c.offs.push(() => ro.disconnect());
  function carry(from, to){
    const k = { from, to, pk:html(`<span class="aln-pk" aria-hidden="true" style="--dm-from:var(--dm-aln-${from.t},var(--dm-${from.t}));--dm-to:var(--dm-aln-${to.t},var(--dm-${to.t}))"></span>`) };
    rows.appendChild(k.pk); links.push(k); place(k);
    const an = REDUCE ? null : k.pk.animate([{ transform:'scaleY(0)' }, { transform:'scaleY(1)' }], { duration:800, easing:'cubic-bezier(.65,0,.35,1)' });
    return an ? an.finished.catch(() => {}) : Promise.resolve();
  }
  async function handoff(from, to, txt){
    const h = html(`<div class="fold shut aln-hf" style="--dm-from:var(--dm-${from.t});--dm-to:var(--dm-${to.t})"><div><div class="aln-hand"><b class="f">${from.n}</b> handed ${txt} to <b class="t">${to.n}</b></div></div></div>`);
    to.el.before(h); void h.offsetWidth; h.classList.remove('shut'); enter($('.aln-hand', h), 80);
    await c.wait(REDUCE ? 0 : 500); await carry(from, to);
    from.el.classList.add('sent'); h.classList.add('lit'); to.el.classList.add('got');
    const av = $('.aln-av', to.el); av.classList.add('ping'); c.later(950, () => av.classList.remove('ping'));
    await c.wait(1300); h.classList.add('shut'); await c.wait(REDUCE ? 0 : 700); h.remove();
  }
  c.run(async () => {
    await c.wait(600);
    const r1 = work(L[0]); act(L[1], L[1].wait); state(L[1], 'waiting');
    await r1; await handoff(L[0], L[1], 'the brief');
    act(L[2], L[2].wait); state(L[2], 'waiting');
    await work(L[1]); await handoff(L[1], L[2], '4 frames');
    await work(L[2]);
    finished = true; root.classList.add('fin'); $('.aln-ic', r).innerHTML = I('ok'); enter($('.aln-ic', r).firstElementChild);
    swap($('.aln-t', r), 'All 3 agents finished'); pb.remove();
  });
});
